import icontract


def digit_sum(n: int) -> int:
    return 0 if n == 0 else n % 10 + digit_sum(n // 10)


@icontract.require(lambda n: n >= 0)
@icontract.ensure(lambda result: result >= 0)
@icontract.ensure(lambda n, result: result == digit_sum(n))
def sumOfDigits(n: int) -> int:
    total = 0
    m = n
    while m > 0:
        total += m % 10
        m //= 10
    return total
